## Why This Is Asked
Tests ability to design a small data-layer primitive using closures, promises, and batching for performance.

## Key Concepts
- Closures and per-key caches
- Promise queuing and batch network calls
- TTL-based eviction and memory safety
- Error handling and cancellation tokens

## Code Example
```javascript
function createBatchingCache(fetcher, { batchDelay = 100, ttl = 5000 } = {}) {
  const cache = new Map(); // key -> { value, expiresAt }
  const inFlight = new Map(); // key -> { promise, resolve, reject }
  let batch = [];
  let timer = null;

  async function flush() {
    const keys = batch;
    batch = [];
    const uniq = Array.from(new Set(keys));
    try {
      const results = await fetcher(uniq);
      uniq.forEach((k, i) => {
        const v = results[i];
        cache.set(k, { value: v, expiresAt: Date.now() + ttl });
        if (inFlight.has(k)) inFlight.get(k).resolve(v);
        inFlight.delete(k);
      });
    } catch (e) {
      uniq.forEach(k => inFlight.get(k)?.reject(e));
      uniq.forEach(k => inFlight.delete(k));
    }
  }

  return {
    get(key) {
      const c = cache.get(key);
      if (c && c.expiresAt > Date.now()) return Promise.resolve(c.value);
      if (inFlight.has(key)) return inFlight.get(key).promise;
      let resolve, reject;
      const p = new Promise((res, rej) => { resolve = res; reject = rej; });
      inFlight.set(key, { promise: p, resolve, reject });
      batch.push(key);
      if (!timer) timer = setTimeout(() => { timer = null; flush(); }, batchDelay);
      return p;
    },
    clear() {
      cache.clear();
      inFlight.clear();
      batch = [];
      if (timer) clearTimeout(timer);
      timer = null;
    }
  };
}
```

## Why This Is Asked
Tests understanding of combining Context with a small Redux-like store, debounce patterns, and memoized rendering for performance.

## Key Concepts
- useReducer + Context for lightweight global store
- Debounce with useEffect
- Memoized selectors with useMemo
- React.memo for granular re-render control
- Cleanup on unmount and dependency changes

## Code Example
```javascript
// store.js
import React from 'react'

export const AppConfigContext = React.createContext({ apiEndpoint: '/api', debounce: 300 })

const initialState = { query: '', results: [] }

function reducer(state, action) {
  switch (action.type) {
    case 'SET_QUERY':
      return { ...state, query: action.payload }
    case 'SET_RESULTS':
      return { ...state, results: action.payload }
    default:
      return state
  }
}

export function useStore() {
  const [state, dispatch] = React.useReducer(reducer, initialState)
  const actions = React.useMemo(() => ({
    setQuery: (q) => dispatch({ type: 'SET_QUERY', payload: q }),
    setResults: (r) => dispatch({ type: 'SET_RESULTS', payload: r })
  }), [])
  return { state, actions }
}
```

```javascript
// DebouncedSearchInput.js
import React from 'react'
export function DebouncedSearchInput({ value, onChange, delay = 300 }) {
  const [local, setLocal] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => onChange(local), delay)
    return () => clearTimeout(id)
  }, [local, delay, onChange])
  React.useEffect(() => setLocal(value), [value])
  return <input value={local} onChange={(e) => setLocal(e.target.value)} />
}
```

